        try {
            if (_storage != null) {
                _storage.addNewRun(name, this);
            }
            TypeSystemDescription desc = instantiate_pipeline();
            if (_cas_poolsize == null) {
                _cas_poolsize = (int) Math.ceil(_workers * 1.5);
