            }
            Instant starttime = Instant.now();
            while (collectionReader.hasNext()) {
                JCas jc = emptyCasDocuments.poll();
                while (jc == null) {
                    jc = emptyCasDocuments.poll();
                }
                collectionReader.getNext(jc.getCas());
