                DebugLevel.INFO);

        DUUIComposer that = this;
        _shutdownHook = new Thread(() -> {
            try {
                that.shutdown();
                addEvent(DUUIEvent.Sender.COMPOSER, "Shutdown Hook finished.");
            } catch (UnknownHostException e) {
                e.printStackTrace();
            }
        });

        Runtime.getRuntime().addShutdownHook(_shutdownHook);
    }

