    private void removeSmallFiles() {
        composer.addEvent(
                DUUIEvent.Sender.READER,
                String.format("Skip files smaller than %d bytes.", builder.minimumDocumentSize));

        composer.addEvent(
                DUUIEvent.Sender.READER,
                String.format("Number of files before skipping %d.", preProcessor.size()));

