    private InputStream decodeDocument(DUUIDocument document, Timer timer) {
        document.setStatus(DUUIStatus.DECODE);

        composer.addEvent(
                DUUIEvent.Sender.READER,
                String.format(
                        "Decoding document %s",
                        document.getPath())
        );

        timer.start();

        InputStream decodedFile;

        try {
            decodedFile = DUUIDocumentDecoder.decode(document);
        } catch (IOException e) {
            return null;
        }
        timer.stop();
        return decodedFile;
    }

