        return _parameters;
    }

    public String getSourceView() {
        String result = _options.get(sourceView);
        if (result == null) {
            return "_InitialView";
        }
        return result;
    }

    public String getTargetView() {
        String result = _options.get(targetView);
        if (result == null) {
            return "_InitialView";
        }
        return result;
    }

